#!/usr/bin/env bash
# Generate a project from each template and run the full gate on it, so the templates always
# produce code that passes. Output goes to target/template-check/ (git-ignored).
set -euo pipefail
cd "$(git rev-parse --show-toplevel)"

out=target/template-check
rm -rf "$out"
for kind in app crate; do
  case $kind in app) dest="$out/apps" ;; crate) dest="$out/crates" ;; esac
  mkdir -p "$dest"
  cargo generate --path "templates/$kind" --destination "$dest" --name "template-check-$kind" \
    --define description="Generated by check-templates" --silent
  (cd "$dest/template-check-$kind" && cargo generate-lockfile --quiet)
  scripts/check.sh "$dest/template-check-$kind"
done
